static int waitfd(int fd,short ev,long long deadline){for(;;){long long rem=deadline-ms();if(rem<=0)return 0;pollfd p{fd,ev,0};int n=poll(&p,1,(int)min(rem,(long long)INT_MAX));if(n<0&&errno==EINTR)continue;if(n<=0)return n;return (p.revents&(ev|POLLERR|POLLHUP|POLLNVAL))?1:0;}}
static bool writeall(int fd,const char*p,size_t n,long long end){while(n){ssize_t w=send(fd,p,n,MSG_NOSIGNAL);if(w>0){p+=w;n-=w;continue;}if(w<0&&(errno==EINTR))continue;if(w<0&&(errno==EAGAIN||errno==EWOULDBLOCK)){if(waitfd(fd,POLLOUT,end)>0)continue;}return false;}return true;}
static bool writeall(int fd,const string&s,long long end){return writeall(fd,s.data(),s.size(),end);}
struct Reader{int fd;string buf;bool eof=false;explicit Reader(int f):fd(f){};int more(long long end){for(;;){char b[16384];ssize_t n=recv(fd,b,sizeof b,0);if(n>0){buf.append(b,n);return 1;}if(n==0){eof=true;return -1;}if(errno==EINTR)continue;if(errno==EAGAIN||errno==EWOULDBLOCK){int r=waitfd(fd,POLLIN,end);if(r>0)continue;return 0;}return -1;}}};
static bool validfield(const string&s){for(unsigned char c:s)if(c==0||c=='\r'||c=='\n'||(c<32&&c!='\t')||c==127)return false;return true;}
