static vector<string> vals(const vector<pair<string,string>>&h,const string&k){vector<string>v;for(auto&p:h)if(p.first==k)v.push_back(p.second);return v;}
static bool has_token(const vector<pair<string,string>>&h,const string&name,const string&v){for(auto&s:vals(h,name))for(auto&t:split(s,','))if(lower(trim(t))==v)return true;return false;}
