static const char* reason(int s){switch(s){case 200:return "OK";case 206:return "Partial Content";case 301:return "Moved Permanently";case 302:return "Found";case 304:return "Not Modified";case 400:return "Bad Request";case 403:return "Forbidden";case 404:return "Not Found";case 405:return "Method Not Allowed";case 408:return "Request Timeout";case 413:return "Payload Too Large";case 416:return "Range Not Satisfiable";case 429:return "Too Many Requests";case 431:return "Request Header Fields Too Large";case 502:return "Bad Gateway";case 504:return "Gateway Timeout";default:return "Error";}}
