static void cacheput(const Req&q,const Config&c,const Response&r,const vector<pair<string,string>>&h){if(q.method!="GET"||r.status!=200||!vals(q.h,"authorization").empty()||!vals(h,"set-cookie").empty())return;bool pub=false,bad=false,got=false;unsigned long long age=0;for(auto&v:vals(h,"cache-control"))for(auto&x:split(lower(v),',')){x=trim(x);if(x=="public")pub=true;if(x=="private"||x=="no-store"||x.compare(0,8,"private=")==0)bad=true;if(x.compare(0,8,"max-age=")==0){unsigned long long n;if(number(trim(x.substr(8)),n)){age=n;got=true;}}}if(!pub||bad||!got||!age||!c.ttl||r.body.size()>(size_t)c.cache)return;bool vary=false;for(auto&v:vals(h,"vary"))for(auto&x:split(lower(v),',')){x=trim(x);if(x!="accept-encoding")return;vary=true;}long long ttl=min((unsigned long long)c.ttl,age>ULLONG_MAX/1000?ULLONG_MAX:age*1000);if(!ttl)return;string key=cachebase(q)+"\n"+(vary?encoding(q):"*");lock_guard<mutex>l(cm);auto it=cache.find(key);if(it!=cache.end()){cacheused-=it->second.bytes;cache.erase(it);}while(cacheused+r.body.size()>(size_t)c.cache&&!cache.empty()){auto victim=cache.begin();for(auto i=cache.begin();i!=cache.end();++i)if(i->second.seq<victim->second.seq)victim=i;cacheused-=victim->second.bytes;cache.erase(victim);}Entry e{r,ms()+ttl,vary?encoding(q):"*",r.body.size(),++cacheseq};cacheused+=e.bytes;cache.emplace(key,move(e));}
struct UpConn{int fd=-1;size_t idx=0;~UpConn(){if(fd>=0)close(fd);}};
static Response proxy(const Req&q,const Config&c,UpConn&uc){if(q.method!="GET"&&q.method!="HEAD"&&q.method!="POST")return err(405);Response cached;if((q.method=="GET"||q.method=="HEAD")&&vals(q.h,"authorization").empty()&&cacheget(q,cached))return cached;size_t idx=rr.fetch_add(1)%c.ups.size();int last=502;for(int attempt=0;attempt<(q.method=="POST"?1:2);attempt++,idx=(idx+1)%c.ups.size()){long long deadline=ms()+c.uptime;if(uc.fd>=0&&uc.idx!=idx){close(uc.fd);uc.fd=-1;}if(uc.fd<0){int fd=connectup(c.ups[idx],deadline);if(fd<0){last=fd==-2?504:502;continue;}uc.fd=fd;uc.idx=idx;}string path="/"+q.path.substr(c.proxy.size())+q.query;string req=q.method+" "+path+" HTTP/1.1\r\nHost: "+c.ups[idx].authority+"\r\n";auto hs=hop(q.h);hs.insert("host");for(auto&p:q.h)if(!hs.count(p.first))req+=p.first+": "+p.second+"\r\n";req+="Content-Length: "+to_string(q.body.size())+"\r\nConnection: keep-alive\r\n\r\n";req+=q.body;if(!writeall(uc.fd,req,deadline)){last=ms()>=deadline?504:502;close(uc.fd);uc.fd=-1;continue;}Reader reader(uc.fd);int st=0;vector<pair<string,string>> h;bool ok=false;for(;;){auto p=reader.buf.find("\r\n\r\n");if(p!=string::npos){if(p+4>(size_t)c.header)break;string raw=reader.buf.substr(0,p+4);reader.buf.erase(0,p+4);if(!upstreamhead(raw,st,h))break;ok=true;break;}if(reader.buf.size()>(size_t)c.header)break;int n=reader.more(deadline);if(n<=0){last=n==0?504:502;break;}}if(!ok){close(uc.fd);uc.fd=-1;continue;}auto cls=vals(h,"content-length"),tes=vals(h,"transfer-encoding");unsigned long long n=0;if(cls.size()>1||(!cls.empty()&&!tes.empty())||(!cls.empty()&&!number(cls[0],n))||tes.size()>1||(!tes.empty()&&lower(trim(tes[0]))!="chunked")){last=502;close(uc.fd);uc.fd=-1;continue;}bool nobody=q.head||st==204||st==304||(st>=100&&st<200);string data;if(!nobody){if(!tes.empty()){int e=chunked(reader,deadline,c.body,c.header,data);if(e){last=ms()>=deadline?504:502;close(uc.fd);uc.fd=-1;continue;}}else if(!cls.empty()){if(n>(unsigned)c.body){last=502;close(uc.fd);uc.fd=-1;continue;}if(getbytes(reader,n,deadline,data)){last=ms()>=deadline?504:502;close(uc.fd);uc.fd=-1;continue;}}else{last=502;close(uc.fd);uc.fd=-1;continue;}}if(!reader.buf.empty()||has_token(h,"connection","close")){close(uc.fd);uc.fd=-1;}Response r;r.status=st;r.body=move(data);if(q.head&&!cls.empty()){r.explicitlen=true;r.length=n;}auto skip=hop(h);for(auto&p:h)if(!skip.count(p.first))add(r,p.first,p.second);cacheput(q,c,r,h);return r;}return err(last);}
static void* worker(void*arg){int fd=(int)(intptr_t)arg;Reader reader(fd);UpConn uc;int count=0;for(;;){shared_ptr<Config> c;{lock_guard<mutex>l(gm);c=cfg;}Req q;int code=gethead(reader,*c,q);if(code<0)break;if(code){sendresp(fd,err(code),q.head,true,c->write);break;}code=body(reader,q,*c);if(code){sendresp(fd,err(code),q.head,true,c->write);break;}count++;bool closeit=q.close||count>=c->maxreq||term;Response r;if(!allow(*c)){r=err(429);add(r,"Retry-After","1");}else if(q.proxy)r=proxy(q,*c,uc);else r=local(q,*c);if(!sendresp(fd,r,q.head,closeit,c->write)||closeit)break;}close(fd);active--;return nullptr;}
int main(int argc,char**argv){signal(SIGPIPE,SIG_IGN);signal(SIGHUP,sig);signal(SIGTERM,sig);if(argc!=3||string(argv[1])!="--config")return 1;cfgpath=argv[2];auto c=make_shared<Config>();if(!config(cfgpath,*c))return 1;cfg=c;int listener=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(listener<0)return 1;int one=1;setsockopt(listener,SOL_SOCKET,SO_REUSEADDR,&one,sizeof one);if(bind(listener,(sockaddr*)&c->listen.sa,sizeof c->listen.sa)<0||listen(listener,4096)<0)return 1;pthread_attr_t attr;pthread_attr_init(&attr);pthread_attr_setdetachstate(&attr,PTHREAD_CREATE_DETACHED);pthread_attr_setstacksize(&attr,131072);while(!term){if(hup){hup=0;auto n=make_shared<Config>();if(config(cfgpath,*n)&&n->listen.authority==c->listen.authority){{lock_guard<mutex>l(gm);cfg=n;c=n;}{lock_guard<mutex>l(cm);cache.clear();cacheused=0;}{lock_guard<mutex>l(ratem);lastref=0;tokens=0;}}}pollfd p{listener,POLLIN,0};int n=poll(&p,1,100);if(n<=0)continue;for(;;){int fd=accept4(listener,nullptr,nullptr,SOCK_NONBLOCK|SOCK_CLOEXEC);if(fd<0){if(errno==EINTR)continue;break;}if(active>=c->maxconn){close(fd);continue;}active++;pthread_t t;if(pthread_create(&t,&attr,worker,(void*)(intptr_t)fd)){active--;close(fd);}}}close(listener);long long end=ms()+c->drain;while(active&&ms()<end)usleep(10000);return 0;}
